CREATE TABLE recruitment_match_result (id BIGINT NOT NULL AUTO_INCREMENT,profile_id BIGINT NOT NULL,position_id BIGINT NOT NULL,match_result VARCHAR(16) NOT NULL,matched_count INT NOT NULL DEFAULT 0,uncertain_count INT NOT NULL DEFAULT 0,not_matched_count INT NOT NULL DEFAULT 0,summary VARCHAR(1000) DEFAULT NULL,created_at DATETIME DEFAULT NULL,updated_at DATETIME DEFAULT NULL,PRIMARY KEY(id),UNIQUE KEY uk_recruitment_match_profile_position(profile_id,position_id),KEY idx_recruitment_match_profile_result(profile_id,match_result),CONSTRAINT fk_recruitment_match_profile FOREIGN KEY(profile_id) REFERENCES user_profile(id) ON DELETE CASCADE,CONSTRAINT fk_recruitment_match_position FOREIGN KEY(position_id) REFERENCES recruitment_position(id) ON DELETE CASCADE);
CREATE TABLE recruitment_match_item (id BIGINT NOT NULL AUTO_INCREMENT,match_result_id BIGINT NOT NULL,requirement_id BIGINT DEFAULT NULL,requirement_type VARCHAR(32) NOT NULL,requirement_level VARCHAR(16) NOT NULL,result VARCHAR(16) NOT NULL,position_requirement TEXT,user_evidence TEXT,reason VARCHAR(1000) DEFAULT NULL,created_at DATETIME DEFAULT NULL,PRIMARY KEY(id),KEY idx_recruitment_match_item_result(match_result_id),CONSTRAINT fk_recruitment_match_item_result FOREIGN KEY(match_result_id) REFERENCES recruitment_match_result(id) ON DELETE CASCADE,CONSTRAINT fk_recruitment_match_item_requirement FOREIGN KEY(requirement_id) REFERENCES recruitment_requirement(id) ON DELETE SET NULL);
